style.css:
@-moz-document domain("youtube.com") {
/* Force YouTube's light mode base to respect custom variables */
    html:not([dark]) {
        --yt-spec-raised-background: #d4e3f0 !important; 
        --yt-spec-menu-background: #d4e3f0 !important;
        --yt-spec-guide-background: #c2d8ec !important;
        --yt-spec-badge-chip-background: #e2ecf5 !important;
        --yt-spec-touch-response: #a1bde6 !important;
        --yt-spec-additive-background: #e2ecf5 !important;
        --yt-spec-text-primary: #102a43 !important;
        --yt-spec-text-secondary: #243b53 !important;
        --yt-spec-text-disabled: #627d98 !important;
    }

    #guide-inner-content, 
    ytd-app[guide-persistent-and-visible] #guide.ytd-app {
        background-color: var(--yt-spec-guide-background) !important;
    }

    ytd-masthead {
        background-color: var(--yt-spec-raised-background) !important;
    }

    /* Updated wallpaper link and position settings */
    body, ytd-app, #content.ytd-app {
        background-image: url("https://r4.wallpaperflare.com/wallpaper/118/736/916/gawr-gura-hololive-blue-eyes-white-hair-hd-wallpaper-6631b6686024bc6e11599a9da016af34.jpg") !important;
        background-size: cover !important;        
        background-position: 60% center !important; /* Adjust this percentage if Gura needs to shift left or right */
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
    }

    #background, 
    #columns.ytd-two-column-browse-results-renderer,
    ytd-page-manager {
        background: transparent !important;
    }
}
